-- id:       rbac-rls-policies
-- title:    RBAC: row-level security policies
-- concept:  pg_policies catalog view
-- rubric:   12 · RBAC in the database
-- purpose:  Every RLS policy: the table, the command it guards, the roles it applies to and its USING expression. Rows with no matching policy are invisible (default deny).
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT tablename, policyname, cmd, roles,
       left(regexp_replace(coalesce(qual, with_check), 's+', ' ', 'g'), 110) AS rule
FROM pg_policies
WHERE schemaname = 'public'
ORDER BY tablename, policyname;
